select public._wave13_upsert_formula_tools('personal-finance-tools',$json$[{"slug":"savings-goal-progress-rate-calculator","title_ar":"حاسبة التقدم نحو هدف الادخار","title_en":"Savings Goal Progress Rate Calculator","expression":"current_savings / savings_goal * 100","fields":[{"key":"current_savings","ar":"المدخرات الحالية","en":"Current savings","min":0,"step":0.01},{"key":"savings_goal","ar":"هدف الادخار","en":"Savings goal","min":1e-06,"step":0.01}],"sort_order":33101},{"slug":"emergency-fund-target-gap-calculator","title_ar":"حاسبة فجوة صندوق الطوارئ","title_en":"Emergency Fund Target Gap Calculator","expression":"target_fund - current_fund","fields":[{"key":"target_fund","ar":"الصندوق المستهدف","en":"Target fund","min":0,"step":0.01},{"key":"current_fund","ar":"الصندوق الحالي","en":"Current fund","min":0,"step":0.01}],"sort_order":33102},{"slug":"debt-payment-rate-calculator","title_ar":"حاسبة نسبة سداد الدين","title_en":"Debt Payment Rate Calculator","expression":"debt_payments / monthly_income * 100","fields":[{"key":"debt_payments","ar":"مدفوعات الدين الشهرية","en":"Monthly debt payments","min":0,"step":0.01},{"key":"monthly_income","ar":"الدخل الشهري","en":"Monthly income","min":1e-06,"step":0.01}],"sort_order":33103},{"slug":"essential-spending-income-ratio-calculator","title_ar":"حاسبة نسبة المصروفات الأساسية للدخل","title_en":"Essential Spending to Income Ratio Calculator","expression":"essential_spending / monthly_income * 100","fields":[{"key":"essential_spending","ar":"المصروفات الأساسية","en":"Essential spending","min":0,"step":0.01},{"key":"monthly_income","ar":"الدخل الشهري","en":"Monthly income","min":1e-06,"step":0.01}],"sort_order":33104},{"slug":"discretionary-income-calculator","title_ar":"حاسبة الدخل المتاح اختياريًا","title_en":"Discretionary Income Calculator","expression":"monthly_income - essential_spending - debt_payments","fields":[{"key":"monthly_income","ar":"الدخل الشهري","en":"Monthly income","min":0,"step":0.01},{"key":"essential_spending","ar":"المصروفات الأساسية","en":"Essential spending","min":0,"step":0.01},{"key":"debt_payments","ar":"مدفوعات الدين","en":"Debt payments","min":0,"step":0.01}],"sort_order":33105},{"slug":"monthly-investment-rate-calculator","title_ar":"حاسبة نسبة الاستثمار الشهري","title_en":"Monthly Investment Rate Calculator","expression":"monthly_investment / monthly_income * 100","fields":[{"key":"monthly_investment","ar":"الاستثمار الشهري","en":"Monthly investment","min":0,"step":0.01},{"key":"monthly_income","ar":"الدخل الشهري","en":"Monthly income","min":1e-06,"step":0.01}],"sort_order":33106},{"slug":"subscription-spend-rate-calculator","title_ar":"حاسبة نسبة مصروف الاشتراكات","title_en":"Subscription Spend Rate Calculator","expression":"subscription_spend / monthly_income * 100","fields":[{"key":"subscription_spend","ar":"مصروف الاشتراكات","en":"Subscription spend","min":0,"step":0.01},{"key":"monthly_income","ar":"الدخل الشهري","en":"Monthly income","min":1e-06,"step":0.01}],"sort_order":33107},{"slug":"annual-expense-run-rate-calculator","title_ar":"حاسبة معدل المصروف السنوي","title_en":"Annual Expense Run Rate Calculator","expression":"monthly_expenses * 12","fields":[{"key":"monthly_expenses","ar":"المصروف الشهري","en":"Monthly expenses","min":0,"step":0.01}],"sort_order":33108},{"slug":"cash-buffer-days-calculator","title_ar":"حاسبة أيام الاحتياطي النقدي","title_en":"Cash Buffer Days Calculator","expression":"cash_balance / daily_expenses","fields":[{"key":"cash_balance","ar":"الرصيد النقدي","en":"Cash balance","min":0,"step":0.01},{"key":"daily_expenses","ar":"المصروف اليومي","en":"Daily expenses","min":1e-06,"step":0.01}],"sort_order":33109},{"slug":"personal-net-cash-flow-calculator","title_ar":"حاسبة التدفق النقدي الشخصي الصافي","title_en":"Personal Net Cash Flow Calculator","expression":"monthly_income - monthly_expenses - debt_payments","fields":[{"key":"monthly_income","ar":"الدخل الشهري","en":"Monthly income","min":0,"step":0.01},{"key":"monthly_expenses","ar":"المصروفات الشهرية","en":"Monthly expenses","min":0,"step":0.01},{"key":"debt_payments","ar":"مدفوعات الدين","en":"Debt payments","min":0,"step":0.01}],"sort_order":33110}]$json$::jsonb);
select public._wave13_upsert_formula_tools('seo-tools',$json$[{"slug":"seo-click-share-calculator","title_ar":"حاسبة حصة نقرات SEO","title_en":"SEO Click Share Calculator","expression":"organic_clicks / total_clicks * 100","fields":[{"key":"organic_clicks","ar":"النقرات العضوية","en":"Organic clicks","min":0,"step":0.01},{"key":"total_clicks","ar":"إجمالي النقرات","en":"Total clicks","min":1e-06,"step":0.01}],"sort_order":33201},{"slug":"seo-impressions-per-page-calculator","title_ar":"حاسبة ظهور SEO لكل صفحة","title_en":"SEO Impressions per Page Calculator","expression":"impressions / indexed_pages","fields":[{"key":"impressions","ar":"مرات الظهور","en":"Impressions","min":0,"step":0.01},{"key":"indexed_pages","ar":"الصفحات المفهرسة","en":"Indexed pages","min":1e-06,"step":0.01}],"sort_order":33202},{"slug":"seo-clicks-per-page-calculator","title_ar":"حاسبة نقرات SEO لكل صفحة","title_en":"SEO Clicks per Page Calculator","expression":"organic_clicks / indexed_pages","fields":[{"key":"organic_clicks","ar":"النقرات العضوية","en":"Organic clicks","min":0,"step":0.01},{"key":"indexed_pages","ar":"الصفحات المفهرسة","en":"Indexed pages","min":1e-06,"step":0.01}],"sort_order":33203},{"slug":"seo-ranking-improvement-rate-calculator","title_ar":"حاسبة تحسن ترتيب SEO","title_en":"SEO Ranking Improvement Rate Calculator","expression":"(old_position - new_position) / old_position * 100","fields":[{"key":"old_position","ar":"الترتيب السابق","en":"Previous position","min":1e-06,"step":0.01},{"key":"new_position","ar":"الترتيب الجديد","en":"New position","min":1e-06,"step":0.01}],"sort_order":33204},{"slug":"seo-traffic-growth-rate-calculator","title_ar":"حاسبة نمو زيارات SEO","title_en":"SEO Traffic Growth Rate Calculator","expression":"(new_visits - old_visits) / old_visits * 100","fields":[{"key":"old_visits","ar":"الزيارات السابقة","en":"Previous visits","min":1e-06,"step":0.01},{"key":"new_visits","ar":"الزيارات الجديدة","en":"New visits","min":0,"step":0.01}],"sort_order":33205},{"slug":"seo-organic-lead-rate-calculator","title_ar":"حاسبة تحويل الزيارات العضوية إلى عملاء محتملين","title_en":"SEO Organic Lead Rate Calculator","expression":"organic_leads / organic_visits * 100","fields":[{"key":"organic_leads","ar":"العملاء المحتملون العضويون","en":"Organic leads","min":0,"step":0.01},{"key":"organic_visits","ar":"الزيارات العضوية","en":"Organic visits","min":1e-06,"step":0.01}],"sort_order":33206},{"slug":"seo-organic-revenue-per-visit-calculator","title_ar":"حاسبة الإيراد العضوي لكل زيارة","title_en":"SEO Organic Revenue per Visit Calculator","expression":"organic_revenue / organic_visits","fields":[{"key":"organic_revenue","ar":"الإيراد العضوي","en":"Organic revenue","min":0,"step":0.01},{"key":"organic_visits","ar":"الزيارات العضوية","en":"Organic visits","min":1e-06,"step":0.01}],"sort_order":33207},{"slug":"seo-pages-per-keyword-calculator","title_ar":"حاسبة الصفحات لكل كلمة مفتاحية","title_en":"SEO Pages per Keyword Calculator","expression":"ranking_pages / ranking_keywords","fields":[{"key":"ranking_pages","ar":"الصفحات المرتبة","en":"Ranking pages","min":0,"step":0.01},{"key":"ranking_keywords","ar":"الكلمات المفتاحية المرتبة","en":"Ranking keywords","min":1e-06,"step":0.01}],"sort_order":33208},{"slug":"seo-indexation-rate-calculator","title_ar":"حاسبة معدل فهرسة الصفحات","title_en":"SEO Indexation Rate Calculator","expression":"indexed_pages / submitted_pages * 100","fields":[{"key":"indexed_pages","ar":"الصفحات المفهرسة","en":"Indexed pages","min":0,"step":0.01},{"key":"submitted_pages","ar":"الصفحات المرسلة","en":"Submitted pages","min":1e-06,"step":0.01}],"sort_order":33209},{"slug":"seo-nonbrand-click-share-calculator","title_ar":"حاسبة حصة النقرات غير المرتبطة بالعلامة","title_en":"SEO Non-brand Click Share Calculator","expression":"nonbrand_clicks / organic_clicks * 100","fields":[{"key":"nonbrand_clicks","ar":"النقرات غير المرتبطة بالعلامة","en":"Non-brand clicks","min":0,"step":0.01},{"key":"organic_clicks","ar":"النقرات العضوية","en":"Organic clicks","min":1e-06,"step":0.01}],"sort_order":33210}]$json$::jsonb);
